// Converts the Unity project's data assets (`../tactics-rpg/Assets`) into TypeScript modules under
// `src/lib/resources/`, which mirrors Unity's `Assets/Resources` folder.
//
//   pnpm convert          regenerate
//   pnpm convert --check  exit non-zero if the generated files are out of date
//
// The converter owns the folders listed in `generatedFolders` and rewrites them wholesale; every
// other file under `src/lib/resources/` is hand-written.
import { mkdir, readdir, readFile, rm, writeFile } from "node:fs/promises"
import path from "node:path"
import { format, resolveConfig } from "prettier"
import { TextAnchor } from "#lib/common/unity/TextAnchor.ts"
import { Alliances } from "#lib/enums/Alliances.ts"
import { Locomotions } from "#lib/enums/Locomotions.ts"
import { Targets } from "#lib/enums/Targets.ts"
import {
	readGuid,
	readScriptableObject,
	readUnityYaml,
	type UnityObject,
	type UnityRef
} from "./unity-yaml.ts"

const root = path.resolve(import.meta.dirname, "..")
export const unityAssets = path.resolve(root, "../tactics-rpg/Assets")
export const resourcesDir = path.resolve(root, "src/lib/resources")

/** Folders under `src/lib/resources/` that are generated. */
export const generatedFolders = [
	"Abilities",
	"Ability Catalog Recipes",
	"Attack Pattern",
	"Conversations",
	"Jobs",
	"Levels",
	"Unit Recipes"
] as const

/** Generated file contents, keyed by path relative to `src/lib/resources/`. */
type Output = Map<string, string>

const json = (value: unknown) => JSON.stringify(value)

function module(source: string, imports: string[], body: string): string {
	return [
		`// Generated by scripts/convert-unity.ts from ${source}. Do not edit.`,
		...imports,
		"",
		body,
		""
	].join("\n")
}

async function assetsIn(folder: string): Promise<string[]> {
	const entries = await readdir(path.join(unityAssets, folder))
	return entries.filter((name) => name.endsWith(".asset")).sort()
}

const basename = (file: string) => file.replace(/\.asset$/, "")

// --- Levels (`Model/LevelData.cs`) -----------------------------------------------------------

interface UnityVector3 {
	x: number
	y: number
	z: number
}

async function convertLevels(out: Output): Promise<void> {
	for (const file of await assetsIn("Resources/Levels")) {
		const data = await readScriptableObject(path.join(unityAssets, "Resources/Levels", file))
		const tiles = (data.tiles as UnityVector3[]).map((v) => [v.x, v.y, v.z])
		out.set(
			`Levels/${basename(file)}.ts`,
			module(
				`Resources/Levels/${file}`,
				[`import type { LevelData } from "#lib/model/LevelData.ts"`],
				`export default { tiles: ${json(tiles)} } satisfies LevelData`
			)
		)
	}
}

// --- Conversations (`Model/ConversationData.cs`, `Model/SpeakerData.cs`) ------------------------

/** `Textures/UI` sprites by GUID, named as in `src/lib/assets/textures/ui/sprites.ts`. */
async function uiSprites(): Promise<Map<string, string>> {
	const folder = path.join(unityAssets, "Textures/UI")
	const sprites = new Map<string, string>()
	for (const file of (await readdir(folder)).filter((name) => name.endsWith(".png"))) {
		sprites.set(await readGuid(path.join(folder, file)), file.replace(/\.png$/, ""))
	}
	return sprites
}

const textAnchorNames = new Map(Object.entries(TextAnchor).map(([name, value]) => [value, name]))

interface UnitySpeakerData {
	messages: string[]
	speaker: UnityRef
	anchor: number
}

async function convertConversations(out: Output): Promise<void> {
	const sprites = await uiSprites()
	for (const file of await assetsIn("Resources/Conversations")) {
		const data = await readScriptableObject(path.join(unityAssets, "Resources/Conversations", file))
		const list = (data.list as UnitySpeakerData[]).map((sd) => {
			const speaker = sprites.get(sd.speaker.guid ?? "")
			const anchor = textAnchorNames.get(sd.anchor as TextAnchor)
			if (!speaker || !anchor) throw new Error(`Unknown speaker or anchor in ${file}`)
			return `{ messages: ${json(sd.messages.map(String))}, speaker: ${json(speaker)}, anchor: TextAnchor.${anchor} }`
		})
		out.set(
			`Conversations/${basename(file)}.ts`,
			module(
				`Resources/Conversations/${file}`,
				[
					`import { TextAnchor } from "#lib/common/unity/TextAnchor.ts"`,
					`import type { ConversationData } from "#lib/model/ConversationData.ts"`
				],
				`export default { list: [${list.join(", ")}] } satisfies ConversationData`
			)
		)
	}
}

// --- Jobs (`Editor/JobParser.cs`: `Settings/*.csv` → `Resources/Jobs/*.prefab`) ------------------

/** `Job.statOrder`, the CSVs' stat columns after the name. */
const jobStatOrder = ["MHP", "MMP", "ATK", "DEF", "MAT", "MDF", "SPD"] as const

/** The rows after the header, split on commas (Unity's `File.ReadAllLines` + `Split(',')`). */
async function csvRows(file: string): Promise<string[][]> {
	const text = await readFile(path.join(unityAssets, file), "utf8")
	return text
		.split(/\r?\n/)
		.slice(1)
		.filter((line) => line.trim() !== "")
		.map((line) => line.split(","))
}

const toInt32 = (value: string) => {
	const n = Number(value)
	if (!Number.isInteger(n)) throw new Error(`Not an integer: ${value}`)
	return n
}

async function convertJobs(out: Output): Promise<void> {
	const jobs = new Map<string, { baseStats: number[]; growStats: number[]; features: string[] }>()
	const getOrCreate = (name: string) => {
		if (!jobs.has(name)) jobs.set(name, { baseStats: [], growStats: [], features: [] })
		return jobs.get(name)!
	}

	// ParseStartingStats: base stats, then EVD, RES, MOV and JMP as StatModifierFeatures.
	for (const elements of await csvRows("Settings/JobStartingStats.csv")) {
		const job = getOrCreate(elements[0]!)
		job.baseStats = elements.slice(1, jobStatOrder.length + 1).map(toInt32)
		job.features = (["EVD", "RES", "MOV", "JMP"] as const).map(
			(type, i) => `{ type: StatTypes.${type}, amount: ${toInt32(elements[8 + i]!)} }`
		)
	}

	// ParseGrowthStats
	for (const elements of await csvRows("Settings/JobGrowthStats.csv")) {
		getOrCreate(elements[0]!).growStats = elements.slice(1).map(Number)
	}

	for (const [name, job] of jobs) {
		out.set(
			`Jobs/${name}.ts`,
			module(
				"Settings/JobStartingStats.csv and Settings/JobGrowthStats.csv",
				[
					`import { StatTypes } from "#lib/enums/StatTypes.ts"`,
					`import type { JobPrefab } from "#lib/view-model-component/actor/Job.ts"`
				],
				`export default { name: ${json(name)}, baseStats: ${json(job.baseStats)}, growStats: ${json(job.growStats)}, features: [${job.features.join(", ")}] } satisfies JobPrefab`
			)
		)
	}
}

// --- Abilities (`Resources/Abilities/<category>/<name>.prefab`) -------------------------------

/** A MonoBehaviour script's class: its base class, and its public fields' C# types. */
interface ScriptClass {
	name: string
	base: string
	fields: Map<string, string>
}

/** The classes of `Scripts/**.cs`, by script GUID and by name. */
async function scriptClasses() {
	const byGuid = new Map<string, ScriptClass>()
	const byName = new Map<string, ScriptClass>()
	const folder = path.join(unityAssets, "Scripts")
	for (const file of await readdir(folder, { recursive: true })) {
		if (!file.endsWith(".cs")) continue
		const source = await readFile(path.join(folder, file), "utf8")
		const declaration = /class\s+(\w+)\s*:\s*(\w+)/.exec(source)
		if (!declaration) continue
		const fields = new Map(
			[...source.matchAll(/public\s+(\w+)\s+(\w+)\s*(?:=[^;]*)?;/g)].map((m) => [m[2]!, m[1]!])
		)
		const cls = { name: declaration[1]!, base: declaration[2]!, fields }
		byGuid.set(await readGuid(path.join(folder, file)), cls)
		byName.set(cls.name, cls)
	}

	const ancestry = (cls: ScriptClass): ScriptClass[] => {
		const base = byName.get(cls.base)
		return [cls, ...(base ? ancestry(base) : [])]
	}
	return { byGuid, ancestry }
}

type Scripts = Awaited<ReturnType<typeof scriptClasses>>

/** What an ability prefab's component is to `AbilityPrefab`, by the class it derives from. */
const abilityParts = {
	BaseAbilityPower: "power",
	AbilityRange: "range",
	AbilityArea: "area",
	AbilityMagicCost: "magicCost",
	HitRate: "hitRate",
	AbilityEffectTarget: "target",
	BaseAbilityEffect: "effect"
} as const

type AbilityPart = (typeof abilityParts)[keyof typeof abilityParts]

/** A prefab's MonoBehaviours as `AbilityPrefab` components (`{ type, ...inspectorFields }`). */
function abilityComponents(scripts: Scripts, behaviours: UnityObject[]) {
	const parts = new Map<AbilityPart, Record<string, unknown>>()
	for (const behaviour of behaviours) {
		const cls = scripts.byGuid.get((behaviour.fields.m_Script as UnityRef).guid ?? "")
		if (!cls) throw new Error(`Unknown script in ${json(behaviour.fields)}`)
		const ancestry = scripts.ancestry(cls)
		if (cls.name === "Ability") continue
		const part = ancestry
			.map((c) => abilityParts[c.name as keyof typeof abilityParts])
			.find(Boolean)
		if (!part) throw new Error(`Not an ability component: ${cls.name}`)
		if (parts.has(part)) throw new Error(`Two ${part} components (${cls.name})`)

		const component: Record<string, unknown> = { type: cls.name }
		for (const [field, value] of Object.entries(behaviour.fields)) {
			if (field.startsWith("m_")) continue
			const type = ancestry.map((c) => c.fields.get(field)).find(Boolean)
			if (type === "bool") component[field] = value === 1
			else if (type === "int" || type === "float") component[field] = Number(value)
			else if (type === "string") component[field] = String(value ?? "")
			else throw new Error(`Unknown field ${cls.name}.${field}`)
		}
		parts.set(part, component)
	}
	return parts
}

/** A prefab's hierarchy: its root GameObject, and how to walk from one object to others. */
async function readPrefab(file: string) {
	const objects = await readUnityYaml(file)
	const byId = new Map(objects.map((o) => [o.fileId, o]))
	const ref = (r: unknown) => byId.get(String((r as UnityRef).fileID))!
	const transforms = objects.filter((o) => o.type === "Transform")
	const transformOf = (go: UnityObject) =>
		transforms.find((t) => (t.fields.m_GameObject as UnityRef).fileID === Number(go.fileId))!
	const behavioursOf = (go: UnityObject) =>
		(go.fields.m_Component as Record<string, UnityRef>[])
			.map((c) => ref(Object.values(c)[0]))
			.filter((o) => o.type === "MonoBehaviour")
	const childrenOf = (go: UnityObject) =>
		(transformOf(go).fields.m_Children as UnityRef[]).map((t) => ref(ref(t).fields.m_GameObject))

	const rootTransform = transforms.find((t) => (t.fields.m_Father as UnityRef).fileID === 0)!
	const root = ref(rootTransform.fields.m_GameObject)
	return { root, ref, behavioursOf, childrenOf }
}

async function convertAbility(scripts: Scripts, file: string): Promise<unknown> {
	const { root: ability, behavioursOf, childrenOf } = await readPrefab(file)
	const parts = abilityComponents(scripts, behavioursOf(ability))
	const children = childrenOf(ability).map((child) => {
		const childParts = abilityComponents(scripts, behavioursOf(child))
		const [hitRate, target, effect] = (["hitRate", "target", "effect"] as const).map((part) => {
			const component = childParts.get(part)
			if (!component) throw new Error(`No ${part} on ${String(child.fields.m_Name)} in ${file}`)
			return component
		})
		return { name: child.fields.m_Name, hitRate, target, effect }
	})
	const magicCost = parts.get("magicCost")?.amount
	return {
		name: ability.fields.m_Name,
		power: parts.get("power"),
		range: parts.get("range"),
		area: parts.get("area"),
		magicCost,
		children
	}
}

async function convertAbilities(out: Output): Promise<void> {
	const scripts = await scriptClasses()
	const folder = "Resources/Abilities"
	const categories = await readdir(path.join(unityAssets, folder), { withFileTypes: true })
	for (const category of categories.filter((entry) => entry.isDirectory())) {
		const files = await readdir(path.join(unityAssets, folder, category.name))
		for (const file of files.filter((name) => name.endsWith(".prefab")).sort()) {
			const source = `${folder}/${category.name}/${file}`
			const prefab = await convertAbility(scripts, path.join(unityAssets, source))
			out.set(
				`Abilities/${category.name}/${file.replace(/\.prefab$/, "")}.ts`,
				module(
					source,
					[
						`import type { AbilityPrefab } from "#lib/view-model-component/ability/AbilityPrefab.ts"`
					],
					`export default ${json(prefab)} satisfies AbilityPrefab`
				)
			)
		}
	}
}

// --- Attack patterns (`View Model Component/AI/`) ----------------------------------------------

/** An attack pattern prefab as `AttackPatternPrefab` source (with `Targets` members). */
async function convertAttackPattern(scripts: Scripts, file: string): Promise<string> {
	const { root, ref, behavioursOf, childrenOf } = await readPrefab(file)
	const classOf = (behaviour: UnityObject) => {
		const cls = scripts.byGuid.get((behaviour.fields.m_Script as UnityRef).guid ?? "")
		if (!cls) throw new Error(`Unknown script in ${json(behaviour.fields)}`)
		return cls.name
	}
	const only = (go: UnityObject) => {
		const behaviours = behavioursOf(go)
		if (behaviours.length !== 1) throw new Error(`${String(go.fields.m_Name)}: not one script`)
		return behaviours[0]!
	}
	// Pickers refer to each other by their GameObject's name, so those must be unique.
	const names = (refs: unknown) =>
		(refs as UnityRef[]).map((r) => json(String(ref(ref(r).fields.m_GameObject).fields.m_Name)))

	const pattern = only(root)
	if (classOf(pattern) !== "AttackPattern") throw new Error(`Not an attack pattern: ${file}`)
	const children = childrenOf(root).map((child) => {
		const behaviour = only(child)
		const type = classOf(behaviour)
		const { fields } = behaviour
		const picker =
			type === "FixedAbilityPicker" ?
				`{ type: "FixedAbilityPicker", target: ${enumMember("Targets", Targets, fields.target)}, ability: ${json(String(fields.ability ?? ""))} }`
			: type === "RandomAbilityPicker" ?
				`{ type: "RandomAbilityPicker", pickers: [${names(fields.pickers).join(", ")}] }`
			:	null
		if (picker === null) throw new Error(`Not an ability picker: ${type}`)
		return { name: String(child.fields.m_Name), picker }
	})
	if (new Set(children.map((c) => c.name)).size !== children.length)
		throw new Error(`Ability pickers with the same name in ${file}`)

	const entries = children.map((c) => `{ name: ${json(c.name)}, picker: ${c.picker} }`)
	return `{ name: ${json(String(root.fields.m_Name))}, pickers: [${names(pattern.fields.pickers).join(", ")}], children: [${entries.join(", ")}] }`
}

async function convertAttackPatterns(out: Output): Promise<void> {
	const scripts = await scriptClasses()
	const folder = "Resources/Attack Pattern"
	const files = await readdir(path.join(unityAssets, folder))
	for (const file of files.filter((name) => name.endsWith(".prefab")).sort()) {
		const source = `${folder}/${file}`
		const prefab = await convertAttackPattern(scripts, path.join(unityAssets, source))
		out.set(
			`Attack Pattern/${file.replace(/\.prefab$/, "")}.ts`,
			module(
				source,
				[
					`import { Targets } from "#lib/enums/Targets.ts"`,
					`import type { AttackPatternPrefab } from "#lib/view-model-component/ai/AttackPatternPrefab.ts"`
				],
				`export default ${prefab} satisfies AttackPatternPrefab`
			)
		)
	}
}

// --- Recipes (`Factory/UnitRecipe.cs`, `Factory/AbilityCatalogRecipe.cs`) -----------------------

/** An enum value as `Enum.Name`, e.g. `Locomotions.Walk`. */
function enumMember(enumName: string, values: Record<string, number>, value: unknown): string {
	const name = Object.entries(values).find(([, v]) => v === value)?.[0]
	if (name === undefined) throw new Error(`No ${enumName} ${String(value)}`)
	return `${enumName}.${name}`
}

async function convertUnitRecipes(out: Output): Promise<void> {
	const folder = "Resources/Unit Recipes"
	for (const file of await assetsIn(folder)) {
		const data = await readScriptableObject(path.join(unityAssets, folder, file))
		const string = (field: string) => json(String(data[field] ?? ""))
		const fields = [
			`name: ${string("m_Name")}`,
			...["model", "job", "attack", "abilityCatalog", "strategy"].map((f) => `${f}: ${string(f)}`),
			`locomotion: ${enumMember("Locomotions", Locomotions, data.locomotion)}`,
			`alliance: ${enumMember("Alliances", Alliances, data.alliance)}`
		]
		out.set(
			`Unit Recipes/${basename(file)}.ts`,
			module(
				`${folder}/${file}`,
				[
					`import { Alliances } from "#lib/enums/Alliances.ts"`,
					`import { Locomotions } from "#lib/enums/Locomotions.ts"`,
					`import type { UnitRecipe } from "#lib/factory/UnitRecipe.ts"`
				],
				`export default { ${fields.join(", ")} } satisfies UnitRecipe`
			)
		)
	}
}

async function convertAbilityCatalogRecipes(out: Output): Promise<void> {
	const folder = "Resources/Ability Catalog Recipes"
	for (const file of await assetsIn(folder)) {
		const data = await readScriptableObject(path.join(unityAssets, folder, file))
		const categories = (data.categories as { name: unknown; entries: unknown[] }[]).map((c) => ({
			name: String(c.name),
			entries: c.entries.map(String)
		}))
		out.set(
			`Ability Catalog Recipes/${basename(file)}.ts`,
			module(
				`${folder}/${file}`,
				[`import type { AbilityCatalogRecipe } from "#lib/factory/AbilityCatalogRecipe.ts"`],
				`export default { categories: ${json(categories)} } satisfies AbilityCatalogRecipe`
			)
		)
	}
}

// ---------------------------------------------------------------------------------------------

/** Runs every converter and returns the formatted output. */
export async function convert(): Promise<Output> {
	const out: Output = new Map()
	await convertAbilities(out)
	await convertAbilityCatalogRecipes(out)
	await convertAttackPatterns(out)
	await convertConversations(out)
	await convertJobs(out)
	await convertLevels(out)
	await convertUnitRecipes(out)

	const formatted: Output = new Map()
	for (const [file, source] of out) {
		const filepath = path.join(resourcesDir, file)
		const options = await resolveConfig(filepath)
		formatted.set(file, await format(source, { ...options, filepath }))
	}
	return formatted
}

/** Generated files that differ from (or are missing from, or extra on) disk. */
export async function stale(out: Output): Promise<string[]> {
	const problems: string[] = []
	for (const [file, contents] of out) {
		const existing = await readFile(path.join(resourcesDir, file), "utf8").catch(() => null)
		if (existing !== contents) problems.push(file)
	}
	for (const folder of generatedFolders) {
		const files = await readdir(path.join(resourcesDir, folder), { recursive: true }).catch(
			() => []
		)
		for (const file of files) {
			const relative = `${folder}/${file}`
			if (file.endsWith(".ts") && !out.has(relative)) problems.push(relative)
		}
	}
	return problems
}

async function write(out: Output): Promise<void> {
	for (const folder of generatedFolders) {
		await rm(path.join(resourcesDir, folder), { recursive: true, force: true })
	}
	for (const [file, contents] of out) {
		const target = path.join(resourcesDir, file)
		await mkdir(path.dirname(target), { recursive: true })
		await writeFile(target, contents)
	}
}

if (import.meta.main) {
	const out = await convert()
	if (process.argv.includes("--check")) {
		const problems = await stale(out)
		if (problems.length > 0) {
			console.error(`Out of date (run \`pnpm convert\`):\n  ${problems.join("\n  ")}`)
			process.exit(1)
		}
	} else {
		await write(out)
		console.log(`Wrote ${out.size} files to ${path.relative(root, resourcesDir)}/`)
	}
}
